1	import { readFileSync } from "node:fs";
2	import {
3	  claim,
4	  createPolicy,
5	  quote,
6	  type Customer,
7	  type Incident,
8	  type Item,
9	  type Policy,
10	} from "./claim-office.js";
11	
12	interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	interface ClaimStep {
18	  op: "claim";
19	  policy: number;
20	  incident: Incident;
21	}
22	
23	type Step = QuoteStep | ClaimStep;
24	
25	interface Scenario {
26	  customer: Customer;
27	  steps: Step[];
28	}
29	
30	type StepResult = { premium: number } | { payout: number; remainingCap: number };
31	
32	/** The policy a claim step reports against, named by the quote step that wrote it. */
33	function policyWrittenBy(policies: Map<number, Policy>, index: number): Policy {
34	  const policy = policies.get(index);
35	  if (policy === undefined) {
36	    throw new Error(`step ${index} did not write a policy`);
37	  }
38	  return policy;
39	}
40	
41	/**
42	 * Works the scenario's steps in order: a quote prices a contract and writes the
43	 * policy the later claim steps report against, and each quote after the first
44	 * is a follow-up contract for the customer.
45	 */
46	function resultsFor(scenario: Scenario): StepResult[] {
47	  const policies = new Map<number, Policy>();
48	  return scenario.steps.map((step, index) => {
49	    if (step.op === "quote") {
50	      const customer = {
51	        ...scenario.customer,
52	        previousContracts: policies.size,
53	      };
54	      const premium = quote(customer, step.items);
55	      policies.set(index, createPolicy(step.items));
56	      return { premium };
57	    }
58	    return claim(policyWrittenBy(policies, step.policy), step.incident);
59	  });
60	}
61	
62	const STDIN_FD = 0;
63	
64	function readStdin(): string {
65	  return readFileSync(STDIN_FD, "utf8");
66	}
67	
68	function main(): void {
69	  const scenario = JSON.parse(readStdin()) as Scenario;
70	  process.stdout.write(JSON.stringify({ results: resultsFor(scenario) }));
71	}
72	
73	try {
74	  main();
75	} catch (error) {
76	  process.stderr.write(`${(error as Error).message}\n`);
77	  process.exit(1);
78	}
