1	/**
2	 * What MHPCO knows about the customer's standing: the facts of their history
3	 * with the office that its policy-wide discount rules are written against.
4	 */
5	export interface Customer {
6	  yearsWithMHPCO: number;
7	  /** Contracts this customer already holds, before the one being quoted. */
8	  previousContracts?: number;
9	}
10	
11	export interface Item {
12	  type: string;
13	  material?: string;
14	  cursed?: boolean;
15	  enchantment?: number;
16	}
17	
18	/**
19	 * How MHPCO prices one insurable type. `kind` is the pricing category the
20	 * office files the type under: main items are priced one by one, components
21	 * are priced as a group so that the building-block offer can be applied.
22	 */
23	interface PriceListEntry {
24	  kind: "main" | "component";
25	  basePremium: number;
26	  insuranceValue: number;
27	}
28	
29	/**
30	 * The MHPCO price list: the office's record of every type it insures at all.
31	 * Absence from this list is the office's rejection condition — MHPCO insures
32	 * exactly what it has priced.
33	 */
34	const PRICE_LIST: Record<string, PriceListEntry> = {
35	  sword: { kind: "main", basePremium: 100, insuranceValue: 1000 },
36	  amulet: { kind: "main", basePremium: 60, insuranceValue: 600 },
37	  staff: { kind: "main", basePremium: 80, insuranceValue: 800 },
38	  potion: { kind: "main", basePremium: 40, insuranceValue: 400 },
39	  rune: { kind: "component", basePremium: 25, insuranceValue: 250 },
40	  moonstone: { kind: "component", basePremium: 25, insuranceValue: 250 },
41	};
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	const CURSE_SURCHARGE_RATE = 0.5;
45	const HIGH_ENCHANTMENT_LEVEL = 5;
46	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
47	const LOYALTY_YEARS = 2;
48	const LOYALTY_DISCOUNT_RATE = 0.2;
49	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
50	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
51	const PROCESSING_FEE = 5;
52	const DEDUCTIBLE_PER_DAMAGE = 100;
53	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
54	const FULL_REIMBURSEMENT_RATE = 1;
55	const HALF_REIMBURSEMENT_LEVEL = 8;
56	const HALF_REIMBURSEMENT_RATE = 0.5;
57	
58	/** MHPCO insures exactly the types on its price list; anything else it turns away. */
59	function priceListEntry(item: Item): PriceListEntry {
60	  const entry = PRICE_LIST[item.type];
61	  if (entry === undefined) {
62	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
63	  }
64	  return entry;
65	}
66	
67	function isComponent(item: Item): boolean {
68	  return priceListEntry(item).kind === "component";
69	}
70	
71	function isMainItem(item: Item): boolean {
72	  return priceListEntry(item).kind === "main";
73	}
74	
75	/** What the customer pays to insure the item, before any offer or modifier. */
76	function itemBasePremium(item: Item): number {
77	  return priceListEntry(item).basePremium;
78	}
79	
80	/**
81	 * What MHPCO insures the item for. A price-list fact: pricing offers such as
82	 * the building block and premium modifiers such as a curse surcharge move what
83	 * the customer pays, never what the office insures the item for.
84	 */
85	function itemInsuranceValue(item: Item): number {
86	  return priceListEntry(item).insuranceValue;
87	}
88	
89	/**
90	 * The building-block offer: MHPCO's standing promotion on a group of alike
91	 * components. It is a pricing offer, not a price-list fact, so it lives beside
92	 * the price list rather than inside it.
93	 */
94	function alikeGroupBasePremium(group: Item[]): number {
95	  return group.length === BLOCK_SIZE
96	    ? BLOCK_BASE_PREMIUM
97	    : group.reduce((total, component) => total + itemBasePremium(component), 0);
98	}
99	
100	/** Components are "alike" when they are of exactly the same type. */
101	function alikeKey(component: Item): string {
102	  return component.type;
103	}
104	
105	function componentsBasePremium(components: Item[]): number {
106	  const alikeGroups = new Map<string, Item[]>();
107	  for (const component of components) {
108	    const key = alikeKey(component);
109	    alikeGroups.set(key, [...(alikeGroups.get(key) ?? []), component]);
110	  }
111	  return [...alikeGroups.values()].reduce(
112	    (total, group) => total + alikeGroupBasePremium(group),
113	    0,
114	  );
115	}
116	
117	function curseSurcharge(item: Item): number {
118	  return item.cursed === true
119	    ? itemBasePremium(item) * CURSE_SURCHARGE_RATE
120	    : 0;
121	}
122	
123	function isHighlyEnchanted(item: Item): boolean {
124	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
125	}
126	
127	function highEnchantmentSurcharge(item: Item): number {
128	  return isHighlyEnchanted(item)
129	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
130	    : 0;
131	}
132	
133	/**
134	 * Item-specific modifiers apply to the base premium of the affected item and
135	 * are added to it, never multiplied onto it. Each risk rule is independent:
136	 * its own condition, its own rate.
137	 */
138	function itemSpecificModifiers(item: Item): number {
139	  return curseSurcharge(item) + highEnchantmentSurcharge(item);
140	}
141	
142	function mainItemsBasePremium(mainItems: Item[]): number {
143	  return mainItems.reduce((total, item) => total + itemBasePremium(item), 0);
144	}
145	
146	/** The policy base premium: the sum of all unmodified item base premiums. */
147	function policyBasePremiumFor(items: Item[]): number {
148	  return (
149	    mainItemsBasePremium(items.filter(isMainItem)) +
150	    componentsBasePremium(items.filter(isComponent))
151	  );
152	}
153	
154	/** The item-specific surcharges of every affected item, summed. */
155	function itemSpecificModifiersFor(items: Item[]): number {
156	  return items
157	    .filter(isMainItem)
158	    .reduce((total, item) => total + itemSpecificModifiers(item), 0);
159	}
160	
161	/**
162	 * Rounding in the MHPCO's favour is a single policy with two arms: an amount
163	 * the customer pays goes up, an amount MHPCO pays out goes down. This is the
164	 * premium arm; it is named for the amount it rounds so that a payout can never
165	 * reach it by mistake.
166	 */
167	function roundPremiumInMHPCOsFavour(premium: number): number {
168	  return Math.ceil(premium);
169	}
170	
171	/** Every item in a quote is treated as a first insurance. */
172	function firstInsuranceSurcharge(policyBasePremium: number): number {
173	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
174	}
175	
176	function isLongStanding(customer: Customer): boolean {
177	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
178	}
179	
180	function loyaltyDiscount(customer: Customer, policyBasePremium: number): number {
181	  return isLongStanding(customer)
182	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
183	    : 0;
184	}
185	
186	function isFollowUpContract(customer: Customer): boolean {
187	  return (customer.previousContracts ?? 0) > 0;
188	}
189	
190	function followUpDiscount(
191	  customer: Customer,
192	  policyBasePremium: number,
193	): number {
194	  return isFollowUpContract(customer)
195	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
196	    : 0;
197	}
198	
199	/**
200	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
201	 * base premiums) and are added to it, never multiplied onto it. Each rule is
202	 * independent: its own condition, its own rate. Surcharges raise the premium
203	 * and discounts lower it; each is computed as a positive amount off the
204	 * unmodified policy base premium and given its sign here.
205	 */
206	function policyWideModifiers(
207	  customer: Customer,
208	  policyBasePremium: number,
209	): number {
210	  return (
211	    firstInsuranceSurcharge(policyBasePremium) -
212	    loyaltyDiscount(customer, policyBasePremium) -
213	    followUpDiscount(customer, policyBasePremium)
214	  );
215	}
216	
217	export function quote(customer: Customer, items: Item[]): number {
218	  const policyBasePremium = policyBasePremiumFor(items);
219	  const premium =
220	    policyBasePremium +
221	    itemSpecificModifiersFor(items) +
222	    policyWideModifiers(customer, policyBasePremium) +
223	    PROCESSING_FEE;
224	  return roundPremiumInMHPCOsFavour(premium);
225	}
226	
227	export interface Damage {
228	  itemType: string;
229	  amount: number;
230	}
231	
232	export interface Incident {
233	  cause: string;
234	  damages: Damage[];
235	}
236	
237	export interface ClaimResult {
238	  payout: number;
239	  remainingCap: number;
240	}
241	
242	/** A policy MHPCO has written: the items it covers and the cap still available. */
243	export interface Policy {
244	  items: Item[];
245	  remainingCap: number;
246	}
247	
248	/** The insurance sum: what MHPCO insures the policy's items for, unmodified. */
249	function insuranceSumFor(items: Item[]): number {
250	  return items.reduce((total, item) => total + itemInsuranceValue(item), 0);
251	}
252	
253	/**
254	 * The cap MHPCO writes a policy for: twice the insurance sum. It is derived
255	 * from the unmodified insurance values alone — premium modifiers such as a
256	 * curse surcharge raise what the customer pays, never what the office owes.
257	 */
258	function capFor(items: Item[]): number {
259	  return insuranceSumFor(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
260	}
261	
262	export function createPolicy(items: Item[]): Policy {
263	  return { items, remainingCap: capFor(items) };
264	}
265	
266	/** Rounded in MHPCO's favour: a payout of 350.5 G is settled at 350 G. */
267	function roundPayoutInMHPCOsFavour(payout: number): number {
268	  return Math.floor(payout);
269	}
270	
271	/**
272	 * A damage entry reports against an insured item when they are of the same
273	 * type: the entry names a type, and the policy's items are what the office has
274	 * written against that name.
275	 */
276	function reportsAgainst(damage: Damage, covered: Item): boolean {
277	  return covered.type === damage.itemType;
278	}
279	
280	/**
281	 * A damage entry paired with the insured item MHPCO has held it against. The
282	 * office settles damages, not items: what it needs to read a claim is which
283	 * insured item answers for which reported damage.
284	 */
285	interface DamagedItem {
286	  item: Item;
287	  damage: Damage;
288	}
289	
290	/**
291	 * A damage reports a loss; MHPCO does not entertain one reported as negative.
292	 * Admissibility is a condition on the entry itself, read when the office takes
293	 * the incident in hand, and independent of what the entry would later earn.
294	 */
295	function admitReportedDamage(damage: Damage): void {
296	  if (damage.amount < 0) {
297	    throw new Error(
298	      `a damage cannot report a negative amount (${damage.amount})`,
299	    );
300	  }
301	}
302	
303	/**
304	 * Which insured item answers for each of an incident's damages. The office
305	 * reads every entry before it settles anything: an inadmissible entry is turned
306	 * away, and so is one it can hold no insured item against. It holds a damaged
307	 * item to account once — an item already spoken for by an earlier entry is no
308	 * longer available to a later one, so an incident that reports more damages of a
309	 * type than the policy covers is turned away naming that type, as is one that
310	 * reports a type the policy never covered at all.
311	 */
312	function damagedItems(policy: Policy, incident: Incident): DamagedItem[] {
313	  const unclaimed = [...policy.items];
314	  return incident.damages.map((damage) => {
315	    admitReportedDamage(damage);
316	    const index = unclaimed.findIndex((covered) =>
317	      reportsAgainst(damage, covered),
318	    );
319	    if (index === -1) {
320	      throw new Error(
321	        `the policy does not cover items of type "${damage.itemType}"`,
322	      );
323	    }
324	    return { item: unclaimed.splice(index, 1)[0], damage };
325	  });
326	}
327	
328	/**
329	 * Damage to a highly enchanted item is reimbursed at half: MHPCO reads a high
330	 * enchantment as the item courting its own misfortune.
331	 */
332	function isHalfReimbursed(item: Item): boolean {
333	  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL;
334	}
335	
336	/**
337	 * The reimbursement clauses of the damaged item, as the rates they carry. Each
338	 * clause is independent: its own condition on the item, its own rate. A clause
339	 * that does not apply is simply absent, and an item the office has written no
340	 * clause against reimburses in full.
341	 *
342	 * MHPCO's dragon-material clause is deliberately absent here, and its absence is
343	 * a conclusion rather than an omission. The clause reimburses in full, so the
344	 * rate it carries is FULL_REIMBURSEMENT_RATE — the same rate an item with no
345	 * clause at all already receives, and the most generous rate there is. Since the
346	 * office settles at the least generous applicable rate, a dragon entry could
347	 * never lower a settlement and could never raise one above the default: it is
348	 * inert at every enchantment level, both where it applies alone and where the
349	 * half-reimbursement clause applies alongside it. Listing it would add an
350	 * element that cannot change an outcome. Should the office ever rewrite its
351	 * conflict rule to read the clauses in the customer's favour, or write a dragon
352	 * clause at a rate other than full, this is where that clause belongs.
353	 */
354	function reimbursementClauseRates(item: Item): number[] {
355	  return isHalfReimbursed(item) ? [HALF_REIMBURSEMENT_RATE] : [];
356	}
357	
358	/**
359	 * The rate MHPCO reimburses the damaged item at. Where several clauses apply
360	 * the office reads them in its own favour and settles at the least generous.
361	 */
362	function reimbursementRate(item: Item): number {
363	  return Math.min(FULL_REIMBURSEMENT_RATE, ...reimbursementClauseRates(item));
364	}
365	
366	/** How much of a damage MHPCO reimburses before its excess is deducted. */
367	function reimbursableDamage(item: Item, damage: Damage): number {
368	  return damage.amount * reimbursementRate(item);
369	}
370	
371	/**
372	 * What one damage earns after the office's excess: the clause decides how much
373	 * of the damage is reimbursable, and the deductible falls on the damage event,
374	 * so every entry in an incident bears it separately — two damaged items, two
375	 * deductibles.
376	 */
377	function damageNetOfDeductible({ item, damage }: DamagedItem): number {
378	  return reimbursableDamage(item, damage) - DEDUCTIBLE_PER_DAMAGE;
379	}
380	
381	/** What the incident earns on its own merits, cap not yet applied. */
382	function reimbursementForIncident(policy: Policy, incident: Incident): number {
383	  return damagedItems(policy, incident).reduce(
384	    (total, damagedItem) => total + damageNetOfDeductible(damagedItem),
385	    0,
386	  );
387	}
388	
389	/**
390	 * The cap MHPCO has left on the policy is the ceiling on every further
391	 * settlement: however much an incident earns, the office pays at most what the
392	 * policy still has available, and a claim against an exhausted cap earns nothing.
393	 */
394	function limitedToRemainingCap(policy: Policy, reimbursement: number): number {
395	  return Math.min(reimbursement, policy.remainingCap);
396	}
397	
398	/**
399	 * The settlement: what MHPCO actually pays. The incident earns on its own
400	 * merits, the policy's remaining cap limits it, and the amount is rounded in
401	 * the office's favour.
402	 */
403	function settlementFor(policy: Policy, incident: Incident): number {
404	  return roundPayoutInMHPCOsFavour(
405	    limitedToRemainingCap(policy, reimbursementForIncident(policy, incident)),
406	  );
407	}
408	
409	/**
410	 * Settling a claim pays the settlement and draws it down from the policy's cap:
411	 * what MHPCO has paid on a policy it will not pay again, so the policy carries
412	 * the drawdown between claims and each settlement lowers the ceiling on the next.
413	 */
414	export function claim(policy: Policy, incident: Incident): ClaimResult {
415	  const payout = settlementFor(policy, incident);
416	  policy.remainingCap -= payout;
417	  return { payout, remainingCap: policy.remainingCap };
418	}
